CREATE TABLE IF NOT EXISTS users(id VARCHAR(36) PRIMARY KEY,username VARCHAR(40) NOT NULL UNIQUE,email VARCHAR(180) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,role VARCHAR(20) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS posts(id VARCHAR(36) PRIMARY KEY,user_id VARCHAR(36) NOT NULL,title VARCHAR(150) NOT NULL,body TEXT NOT NULL,category VARCHAR(30) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'published',views BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS comments(id VARCHAR(36) PRIMARY KEY,post_id VARCHAR(36) NOT NULL,user_id VARCHAR(36) NOT NULL,body VARCHAR(2000) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(post_id) REFERENCES posts(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS reactions(post_id VARCHAR(36) NOT NULL,user_id VARCHAR(36) NOT NULL,kind VARCHAR(16) NOT NULL,active BOOLEAN NOT NULL,version BIGINT NOT NULL DEFAULT 1,PRIMARY KEY(post_id,user_id,kind),FOREIGN KEY(post_id) REFERENCES posts(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS revoked_tokens(token_id VARCHAR(100) PRIMARY KEY,expires_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS email_codes(email VARCHAR(180) PRIMARY KEY,code_hash VARCHAR(100) NOT NULL,expires_at TIMESTAMP NOT NULL,last_sent TIMESTAMP NOT NULL,attempts INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS audit_logs(id VARCHAR(36) PRIMARY KEY,actor VARCHAR(80) NOT NULL,action VARCHAR(80) NOT NULL,target VARCHAR(80) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS mail_outbox(id VARCHAR(36) PRIMARY KEY,email VARCHAR(180) NOT NULL,code VARCHAR(6) NOT NULL,state VARCHAR(20) NOT NULL DEFAULT 'pending',attempts INT NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS mail_deliveries(id VARCHAR(36) PRIMARY KEY,sent_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS knowledge(id VARCHAR(36) PRIMARY KEY,title VARCHAR(180) NOT NULL,content TEXT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
